# generated by Codex gpt-6.1-sol on 2026-10-09 for Ivo Matijasevic
"""Check both patches against tag files and execute their 12 and 7 additions."""
from pathlib import Path
import json,re,shutil,subprocess
from runner import run, B, R, H
from schemata import brace_end
from portable import portable
from upstream_patch import OPTIONAL

def main():
    root=B/'target/patch-check'
    if root.exists():shutil.rmtree(root)
    mapping=json.loads((B/'coretests-test-map.json').read_text())['tests']
    optional={mapping[f'M{id:03}'] for ids in OPTIONAL.values() for id in ids}
    expected=set(mapping.values())
    partitions=[('main','coretests-net.patch',expected-optional),('optional','coretests-net-optional.patch',optional)]
    tests=[]
    for label,filename,names in partitions+[('combined',None,expected)]:
        tree=root/label
        for stem in ['ip_addr','parser','socket_addr']:
            dest=tree/'library/coretests/tests/net'/f'{stem}.rs'
            dest.parent.mkdir(parents=True,exist_ok=True)
            shutil.copyfile(R/f'upstream-tests-1.99.0/library_coretests_tests_net_{stem}.rs',dest)
        patches=[B/filename] if filename else [B/name for _,name,_ in partitions]
        prefix='patch' if label=='main' else 'patch-'+label
        run(prefix+'-git-apply-check',['git','-C',str(tree),'apply','--check',*[str(p) for p in patches]])
        for path in patches:
            for flag,action in [('--dry-run','dry-run'),('','apply')]:
                cmd=['patch','-p1','-d',str(tree)]+([flag] if flag else [])
                p=subprocess.run(cmd,input=path.read_text(),text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
                receipt=prefix+'-'+action+('-'+path.stem if label=='combined' else '')
                (B/'evidence/gen'/f'{receipt}.txt').write_text(H+'command = '+portable(repr(cmd))+' < '+path.name+'\n'+portable(p.stdout)+f'\nexit_code = {p.returncode}\n')
                assert p.returncode==0,p.stdout
        found=[]
        for p in tree.rglob('*.rs'):
            source=p.read_text()
            for match in re.finditer(r'#\[test\]\nfn (\w+)\(\) \{',source):
                if match[1] not in expected:continue
                found.append((match[1],source[match.start():brace_end(source,source.index('{',match.start()))+1]))
        assert {name for name,_ in found}==names and len(found)==len(names)
        if label=='combined':tests=found
    source=root/'proposed.rs'
    source.write_text('// generated by Codex gpt-6.1-sol on 2026-10-09 for Ivo Matijasevic\nuse core::net::*;\n'+'\n\n'.join(text for _,text in tests)+'\n')
    exe=root/'proposed'
    run('patch-build',['rustc','+1.99.0','--edition=2024','--test',str(source),'-o',str(exe)])
    result=run('patch-tests',[str(exe),'--test-threads=1'])
    assert 'test result: ok. 19 passed; 0 failed;' in result.stdout
    for label,_,names in partitions:
        cmd=[str(exe),'--test-threads=1']
        for name in sorted(expected-names):cmd+=['--skip',name]
        result=run('patch-'+label+'-tests',cmd)
        assert f'test result: ok. {len(names)} passed; 0 failed;' in result.stdout
    print('PATCH PASS: both patches apply separately and together; 12 behavioural tests and 7 optional snapshots pass on real std 1.99.0')
if __name__=='__main__':main()
